public static class ApiAcceptance {
 const int A=51001,B=51002,C=51003;const long Epoch=1700000000000L;
 static string xaml;static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=16000000};static readonly List<object> cases=new List<object>();static int assertions,failures;
 static string Id(char c){return new string(c,64);}static string Session(int pid){return pid.ToString("x32");}
 static void Check(bool ok,string message){assertions++;if(!ok)throw new Exception(message);}
 static void Throws(Action a,string message){bool threw=false;try{a();}catch{threw=true;}Check(threw,message);}
 static Dictionary<string,object> Scope(long input=200,long read=100,long reported=20,string id=null,string source="offline_fixture",long? observed=null,long? requests=null,long unknown=0,long write=0){return new Dictionary<string,object>{{"scopeId",id??Id('b')},{"profileId","fixture"},{"protocol","openai-chat"},{"source",source},{"requests",requests??reported},{"reportedRequests",reported},{"inputTokens",input},{"cacheObservedInputTokens",observed??input},{"cacheReadTokens",read},{"cacheWriteTokens",write},{"outputTokens",reported},{"unknownUsageRequests",unknown}};}
 static Dictionary<string,object> Frame(int pid,long seq,long now,Dictionary<string,object>[] scopes,string session=null){return new Dictionary<string,object>{{"schema",3},{"kind","api"},{"pid",pid},{"version","0.1.1"},{"processSession",session??Session(pid)},{"sequence",seq},{"createdAt",Epoch+now},{"device","off"},{"scopes",scopes}};}
 sealed class F:IDisposable {
  public long Now=1000;public readonly Dictionary<int,long> identities=new Dictionary<int,long>{{A,1},{B,2},{C,3}};readonly Dictionary<int,long> seq=new Dictionary<int,long>();
  public readonly ApiReceiver Receiver;public readonly ApiHistory History=new ApiHistory();public readonly Window Window;
  public F(bool allow=true){Receiver=new ApiReceiver(()=>Now,p=>identities.ContainsKey(p)?(long?)identities[p]:null,allow);Window=(Window)XamlReader.Parse(File.ReadAllText(xaml,Encoding.UTF8));var root=(FrameworkElement)Window.Content;root.Measure(new Size(440,900));root.Arrange(new Rect(0,0,440,900));root.UpdateLayout();}
  public void Select(int pid,string id=null){Receiver.SelectAndRender(pid,id??Id('b'),v=>MonitorApp.PaintApi(Window,History,v,true));}
  public ApiTicket Reserve(int pid){return Receiver.Reserve(pid);}
  public bool Send(int pid,long input=200,long read=100,long reported=20,string id=null,bool paint=true,string source="offline_fixture",long? observed=null,long? requests=null,long unknown=0,string session=null,long write=0,long sequenceStep=1){Now+=10;long n;seq.TryGetValue(pid,out n);seq[pid]=n+=sequenceStep;var t=Reserve(pid);Receiver.MarkBytes(t);bool ok=Receiver.Commit(t,ApiCodec.Parse(Json.Serialize(Frame(pid,n,Now,new[]{Scope(input,read,reported,id,source,observed,requests,unknown,write)},session)),(uint)pid,Epoch+Now));if(paint)Paint();return ok;}
  public void Paint(){Receiver.Render(v=>MonitorApp.PaintApi(Window,History,v,true));}
  public string Text(string name){return ((TextBlock)Window.FindName(name)).Text;}
  public void Empty(){Check(Receiver.Capture().Current==null,"no adopted selected receipt");Check(History.Baseline==null,"no baseline");Check(Text("ApiTokenValue")=="未测量"&&Text("ApiRateValue")=="未测量","empty API token and rate both explicitly unmeasured");Check(((Canvas)Window.FindName("ApiTokenChart")).Children.Count==0&&((Canvas)Window.FindName("ApiRateChart")).Children.Count==0,"old curves cleared");}
  public void Dispose(){Window.Close();}
 }
 static void Run(string id,Action action){try{action();cases.Add(new{id,passed=true});}catch(Exception e){failures++;cases.Add(new{id,passed=false,error=e.ToString()});}}
 static void Ready(F f){f.Select(B);f.Send(B);f.Send(B,220,110,22);f.Send(B,240,120,24);Check(f.History.Tokens=="40"&&f.History.Rate=="50.0%","known scope rate and endpoint token subtraction");}
 static void Cases(){
  Run("API00 no snapshot and null view explicitly unmeasured",()=>{var history=new ApiHistory();Check(history.State=="无有效数据"&&history.Tokens=="未测量"&&history.Rate=="未测量","fresh API history keeps missing counters unmeasured");history.Update(null);Check(history.State=="无有效数据"&&history.Tokens=="未测量"&&history.Rate=="未测量"&&history.Points.Count==0,"null API view neither invents zero nor retains curves");using(var f=new F()){f.Select(B);f.Paint();f.Empty();}});
  Run("API01 codec valid five protocols",()=>{foreach(string p in new[]{"openai-responses","openai-chat","deepseek-chat","anthropic-messages","gemini"}){var s=Scope();s["protocol"]=p;var f=ApiCodec.Parse(Json.Serialize(Frame(B,1,1000,new[]{s})),B,Epoch+1000);Check(f.Scopes[0].Protocol==p,"accepted exact protocol");}});
  Run("API02 codec PID/session/version/device rejection",()=>{foreach(string k in new[]{"pid","processSession","version","device"}){var f=Frame(B,1,1000,new[]{Scope()});f[k]=k=="pid"?(object)A:k=="device"?"cuda":k=="version"?"0.6.8":"invalid";Throws(()=>ApiCodec.Parse(Json.Serialize(f),B,Epoch+1000),"reject invalid "+k);}});
  Run("API03 missing null negative fractional excessive counters",()=>{foreach(object bad in new object[]{null,-1,0.25,9007199254740992m,"123"}){var s=Scope();s["inputTokens"]=bad;Throws(()=>ApiCodec.Parse(Json.Serialize(Frame(B,1,1000,new[]{s})),B,Epoch+1000),"reject malformed numeric counter");}var missing=Scope();missing.Remove("requests");Throws(()=>ApiCodec.Parse(Json.Serialize(Frame(B,1,1000,new[]{missing})),B,Epoch+1000),"missing key rejected");});
  Run("API04 bounded body/scope count/duplicates",()=>{var seventeen=Enumerable.Range(0,17).Select(i=>Scope(id:i.ToString("x64"))).ToArray();Throws(()=>ApiCodec.Parse(Json.Serialize(Frame(B,1,1000,seventeen)),B,Epoch+1000),"17 scopes rejected");Throws(()=>ApiCodec.Parse(Json.Serialize(Frame(B,1,1000,new[]{Scope(),Scope()})),B,Epoch+1000),"duplicate scope rejected");Throws(()=>ApiCodec.Parse(new string(' ',16385),B,Epoch),"oversize rejected");});
  Run("API05 codec no credentials/untrusted text",()=>{var s=Scope();s["apiKey"]="fixture-only";Throws(()=>ApiCodec.Parse(Json.Serialize(Frame(B,1,1000,new[]{s})),B,Epoch+1000),"extra text excluded");s=Scope();s["profileId"]="unsafe\nprofile";Throws(()=>ApiCodec.Parse(Json.Serialize(Frame(B,1,1000,new[]{s})),B,Epoch+1000),"profile control chars rejected");});
