  Run("API18 production filters offline fixture scopes",()=>{using(var f=new F(false)){f.Select(B);f.Send(B);Check(f.Receiver.Choices().Length==0,"offline fixtures hidden in production choices");f.Empty();f.Send(B,220,110,22,source:"interface_reported");f.Send(B,220,110,22,source:"interface_reported");Check(f.Receiver.Choices().Length==1,"real interface source selectable");}});
