  Run("API31 current candidate labels and API old candidate rejection",()=>{using(var f=new F()){var revision=System.Text.RegularExpressions.Regex.Match(MonitorApp.UiVersion,@"\A0\.1\.1-ui\.(\d+)\z");Check(revision.Success&&typeof(ApiBridge).Assembly.GetName().Version.ToString()=="0.1.1."+revision.Groups[1].Value,"UI revision identity is independent of unchanged API wire version0.1.1");Check(f.Text("ChartSource").Contains(MonitorApp.UiVersion)&&!f.Text("ChartSource").Contains("0.6.11"),"initial XAML does not retain experimental UI version");Check(f.Window.Title.Contains(MonitorApp.UiVersion)&&f.Text("WindowIdentity").Contains(MonitorApp.UiVersion),"initial title and identity carry current candidate label");var old=Frame(B,1,1000,new[]{Scope()});old["version"]="0.1.0";Throws(()=>ApiCodec.Parse(Json.Serialize(old),B,Epoch+1000),"API old candidate schema version not silently attributed to new candidate");}});
