 static object Stress(){using(var f=new F()){f.Select(B);for(int i=0;i<8192;i++)Check(f.Send(B,200+i,100+i/2,20+i,paint:false),"8192 selected scope frames accepted");Check(f.Receiver.Capture().Receipts.Length==8192,"full bounded receiver window");var process=Process.GetCurrentProcess();GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();long managedBefore=GC.GetTotalMemory(false),rssBefore=process.WorkingSet64;double cpuBefore=process.TotalProcessorTime.TotalMilliseconds;var samples=new List<double>();long peakRss=rssBefore;
   for(int i=0;i<24;i++){var clock=Stopwatch.StartNew();f.Paint();var token=(Canvas)f.Window.FindName("ApiTokenChart");var bitmap=new RenderTargetBitmap(175,54,96,96,PixelFormats.Pbgra32);bitmap.Render(token);samples.Add(clock.Elapsed.TotalMilliseconds);process.Refresh();peakRss=Math.Max(peakRss,process.WorkingSet64);Check(f.History.Tokens=="8,191"&&f.History.Points.Count==8190,"8192-frame refresh exact deltas no lost points");Check(token.Children.Count<=2,"bounded drawing visuals");}
   double cpu=process.TotalProcessorTime.TotalMilliseconds-cpuBefore;GC.Collect();GC.WaitForPendingFinalizers();GC.Collect();long managedAfter=GC.GetTotalMemory(false);Check(f.Receiver.Capture().Receipts.Length==8192,"refresh never counts as new receipt");Check(!f.Send(B,9000,4400,9000,paint:false),"frame8193 explicitly invalidates instead of dropping unknown interval");f.Paint();f.Empty();var sorted=samples.OrderBy(v=>v).ToArray();return new{frames=8192,refreshes=24,visibleWindowOpened=false,refreshMilliseconds=samples,medianMs=(sorted[11]+sorted[12])/2,p95Ms=sorted[22],maxMs=sorted.Last(),cpuMilliseconds=cpu,managedBefore,managedAfter,rssBefore,peakRss,afterRss=process.WorkingSet64,scope="offline_fixture; offscreen WPF layout/raster only; no visible dispatcher responsiveness or long-run leak proof"};
  }}
 static void Wait(Func<bool> condition){var wait=Stopwatch.StartNew();while(!condition()&&wait.ElapsedMilliseconds<1600)Thread.Sleep(5);}
 static void WritePipe(string name,string text,Func<bool> done){using(var client=new NamedPipeClientStream(".",name,PipeDirection.Out)){client.Connect(1000);byte[] bytes=Encoding.UTF8.GetBytes(text);client.Write(bytes,0,bytes.Length);client.Flush();Wait(done);}}
 static object Pipe(){
  string name="cachepilot-api-test-"+Guid.NewGuid().ToString("N");int processId=Process.GetCurrentProcess().Id;
  using(var bridge=new ApiBridge(name,true)){
   bridge.Receiver.Select(processId,Id('b'));bridge.Start();
   string text=Json.Serialize(Frame(processId,1,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()-Epoch,new[]{Scope()}))+"\n";
   WritePipe(name,text,()=>bridge.Receiver.Capture().Current!=null);Check(bridge.Receiver.Capture().Current!=null,"random pipe actual OS PID authenticated; failure="+bridge.LastFailure);
   Throws(()=>{using(var second=new ApiBridge(name,true))second.Start();},"first-instance exclusivity");
   int rejected=bridge.Rejected;
   text=Json.Serialize(Frame(processId+1,2,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()-Epoch,new[]{Scope()}))+"\n";
   WritePipe(name,text,()=>bridge.Rejected>rejected);Check(bridge.Rejected>rejected&&bridge.Receiver.Capture().Current==null,"wire claimed different PID cannot become data source");
   text=Json.Serialize(Frame(processId,2,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()-Epoch,new[]{Scope()}))+"\n";
   WritePipe(name,text,()=>bridge.Receiver.Capture().Current!=null);Check(bridge.Receiver.Capture().Current!=null,"recovery after wire PID mismatch");
   rejected=bridge.Rejected;var deadline=Stopwatch.StartNew();using(var idle=new NamedPipeClientStream(".",name,PipeDirection.Out)){idle.Connect(1000);idle.WriteByte((byte)'{');idle.Flush();Wait(()=>bridge.Rejected>rejected);}
   Check(bridge.Rejected>rejected&&deadline.ElapsedMilliseconds<1400,"500ms partial frame deadline releases pipe");double timeoutElapsed=deadline.Elapsed.TotalMilliseconds;
   text=Json.Serialize(Frame(processId,3,DateTimeOffset.UtcNow.ToUnixTimeMilliseconds()-Epoch,new[]{Scope()}))+"\n";
   WritePipe(name,text,()=>bridge.Receiver.Capture().Current!=null);Check(bridge.Receiver.Capture().Current!=null,"valid wire frame after timeout recovers");
   rejected=bridge.Rejected;WritePipe(name,new string(' ',16384)+"\n",()=>bridge.Rejected>rejected);Check(bridge.Rejected>rejected,"16385 byte frame refused");
   bridge.Dispose();Check(!bridge.Running,"dispose releases server task");using(var reopened=new ApiBridge(name,true)){reopened.Start();Check(reopened.Running,"close releases pipe for next owner");}
   return new{isolatedPipe=true,actualProcessId=processId,released=true,wireWrongPidRejected=true,partialFrameTimeoutMs=timeoutElapsed,oversizeRejected=true,productionPipeAccessed=false};
  }
 }
 static object LocalStress(){
  long now=1000;var receiver=new MonitorReceiver(()=>now,()=>Epoch+now,p=>true,p=>1);var history=new MonitorHistory();var window=(Window)XamlReader.Parse(File.ReadAllText(xaml,Encoding.UTF8));var root=(FrameworkElement)window.Content;root.Measure(new Size(440,900));root.Arrange(new Rect(0,0,440,900));root.UpdateLayout();receiver.Select(B);
