   var t=receiver.Reserve(B);receiver.MarkBytes(t);Check(receiver.Commit(t,FrameCodec.Parse(Json.Serialize(raw),B,Epoch+now),0),"local8192 receipt accepted");receiver.EndTransport(t,true);
