  var sorted=samples.OrderBy(v=>v).ToArray();window.Close();return new{source="offline_fixture",frames=8192,refreshes=24,medianMs=(sorted[11]+sorted[12])/2,p95Ms=sorted[22],maxMs=sorted.Last(),refreshMilliseconds=samples,cpuMilliseconds=process.TotalProcessorTime.TotalMilliseconds-cpuBefore,rssBefore,peakRss,scope="offscreen layout/raster only; no visible-window responsiveness or long-run leak proof"};
 }
